impl Actor {
    fn new(
        scene: u64,
        class: &'static str,
        parent: Option<TableId>,
        load_name: Option<Vec<u8>>,
    ) -> Self {
        Self {
            scene,
            load_name,
            current: crate::SongLuaOverlayState::default().into(),
            queue: VecDeque::new(),
            capture: None,
            preparation_getters: None,
            hibernate: 0.0,
            update_rate: 1.0,
